import { ReactNode } from 'react';
import { ExperimentManifest, ProjectItem } from '../types/project';
import {
    AfterglowIcon,
    CosmicTimelineIcon,
    CosmoIcon,
    DysonIcon,
    GenericExperimentIcon,
    PelagicIcon,
    ProductionPanicIcon,
    StarsRemainIcon,
} from '../components/Icons';
// Generated by scripts/build-registry.mjs from every apps/*/experiment.json.
import registry from './experiments.generated.json';

/** Manifest `icon` value -> component. Unknown or missing names fall back to a generic flask. */
const icons: Record<string, ReactNode> = {
    afterglow: <AfterglowIcon />,
    'cosmic-timeline': <CosmicTimelineIcon />,
    cosmo: <CosmoIcon />,
    dyson: <DysonIcon />,
    pelagic: <PelagicIcon />,
    'production-panic': <ProductionPanicIcon />,
    'the-stars-remain': <StarsRemainIcon />,
};

const toProjectItem = (experiment: ExperimentManifest): ProjectItem => ({
    id: experiment.id,
    href: experiment.route ?? '/',
    category: experiment.category,
    title: experiment.title,
    description: experiment.description,
    tag: experiment.tag,
    ctaText: experiment.cta ?? 'Enter',
    glowColor: experiment.accent as `#${string}`,
    icon: icons[experiment.icon ?? ''] ?? <GenericExperimentIcon />,
    number: experiment.number,
    status: experiment.status,
    date: experiment.date,
    weightKB: experiment.weightKB,
    media: experiment.media,
    input: experiment.input,
});

const experiments = (registry as ExperimentManifest[]).map(toProjectItem);

/** Experiments you can open today. */
export const projectsData: ProjectItem[] = experiments.filter((experiment) => experiment.status !== 'planned');

/** Roadmap entries (status "planned"). Not linked anywhere yet. */
export const plannedData: ProjectItem[] = experiments.filter((experiment) => experiment.status === 'planned');
